CREATE TABLE payment_gateway_attempts (id VARCHAR(64) PRIMARY KEY,payment_intent_id VARCHAR(64) NOT NULL,provider VARCHAR(32) NOT NULL,kind VARCHAR(32) NOT NULL,attempt_no INTEGER NOT NULL,outcome VARCHAR(32) NOT NULL,detail VARCHAR(500),created_at TIMESTAMP NOT NULL,CONSTRAINT uq_gateway_attempt_no UNIQUE(payment_intent_id,attempt_no));
CREATE INDEX ix_gateway_attempt_intent ON payment_gateway_attempts(payment_intent_id); CREATE INDEX ix_gateway_attempt_provider ON payment_gateway_attempts(provider);
CREATE TABLE payment_gateway_reconciliations (id VARCHAR(64) PRIMARY KEY,payment_intent_id VARCHAR(64) NOT NULL,provider VARCHAR(32) NOT NULL,provider_reference VARCHAR(160),provider_status VARCHAR(30) NOT NULL,local_status VARCHAR(30) NOT NULL,matched BOOLEAN NOT NULL,note VARCHAR(500),checked_by VARCHAR(64) NOT NULL,checked_at TIMESTAMP NOT NULL);
CREATE INDEX ix_gateway_reconciliation_intent ON payment_gateway_reconciliations(payment_intent_id); CREATE INDEX ix_gateway_reconciliation_provider ON payment_gateway_reconciliations(provider); CREATE INDEX ix_gateway_reconciliation_matched ON payment_gateway_reconciliations(matched); CREATE INDEX ix_gateway_reconciliation_checked_at ON payment_gateway_reconciliations(checked_at);
